window.__posterData({"id": "gustaf-jonsson", "name": "Gustaf Jonsson", "folder": "GustafJonsson_RavePoster_AI_DIK_HT26.zip", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js"], "links": ["<link\n      href=\"https://fonts.googleapis.com/css2?family=Monoton&family=Orbitron:wght@700&display=swap\"\n      rel=\"stylesheet\"\n    />"], "css": "html,\nbody {\n  margin: 0;\n  padding: 0;\n}\n\ncanvas {\n  display: block;\n}", "code": "/*\n  REFLEKTION \n\n  Vad AI:n gjorde annorlunda: Min kod var kort och hade många hårdkodade\n  siffror. AI:n delade upp den i små funktioner (drawTexts, drawCircles,\n  getMotion) och samlade alla inställningar i konstanter överst. Den använde\n  också saker jag inte kunde, som async/await, .then/.catch och blendMode(ADD).\n  Jag förstår inte allt, men koden blev tydligare än min egen.\n\n  Där jag bad om något specifikt: Jag bad AI:n refaktorera utan att ändra\n  funktionen, och det såg exakt likadant ut efteråt. Jag bad att cirklarna\n  skulle byta färg med texten och att allt skulle röra sig efter första\n  klicket, att RAVE skulle bli större och namnet mindre med bättre fonter, och\n  att den skulle laga att sidan bara laddade. Allt fungerade.\n\n  Vad AI:n valde själv: När jag bad om något roligt valde den laserstrålar\n  från cirklarna till musen. Jag blev glatt överraskad, för det passar\n  rave-temat. Den lade också till mjuk start på rörelsen, flimmer i lasrarna\n  och fonterna Monoton och Orbitron utan att jag bad om det. Jag gillar det\n  mesta, men jag hade velat välja bland några alternativ.\n\n  Designkritik av slutresultatet:\n  - Fungerar bra: RAVE är störst och drar blicken först, så hierarkin är\n    tydlig. Neonfärgerna, fonten och lasrarna hör ihop och ger en stark\n    ravekänsla. Texten, cirklarna och lasrarna har alltid samma färg, vilket\n    ger ett enhetligt intryck. Cirklarna ramar in postern, och rörelsen är\n    lugn nog att inte störa.\n  - Fungerar mindre bra: Monoton har tunna linjer och kan bli svår att läsa\n    över en ljus eller rörig del av bilden, särskilt i gult. Namnet på 18 px\n    är litet. Tolv lasrar kan bli rörigt och täcka rubriken. Postern saknar\n    datum, plats och tid, så den är mer en stämningsbild än en riktig\n    informationspost. Ingen text säger att man ska klicka, så man kan missa\n    att något händer.\n  - Nästa steg: En mörk toning över bilden för bättre kontrast, större namn,\n    färre eller svagare lasrar, och en liten ledtråd om att klicka.\n\n  Det jag tar med mig: AI:n är bra på struktur och på idéer jag inte tänkt på,\n  men den gör egna val och jag förstår inte allt den skriver. Därför måste\n  jag ge tydliga instruktioner och själv granska både koden och designen.\n*/\n// --- Inställningar ---\nconst CANVAS_W = 600;\nconst CANVAS_H = 800;\nconst IMAGE_FILE = \"sebastiaan-stam-OSNHWe24YV4-unsplash.jpg\";\n\nconst TEXT_COLORS = [\"#ff69b4\", \"#ffff00\", \"#32cd32\"]; // rosa, gul, grön\n\nconst TITLE = { text: \"RAVE\", size: 130, y: 230, font: \"Monoton\" };\nconst NAME = { text: \"Gustaf Jonsson\", size: 18, y: 275, font: \"Orbitron\" };\n\nconst CIRCLE = { count: 6, spacing: 108, margin: 30, diameter: 20 };\n\n// Rörelse som startar efter första klicket\nconst MOVE = {\n  circleAmp: 8, // hur långt cirklarna rör sig upp och ner (px)\n  circleSpeed: 2, // hur snabbt de rör sig\n  circlePhase: 0.8, // fasförskjutning mellan cirklarna (ger en vågeffekt)\n  textAmp: 6, // hur långt texten rör sig (px)\n  textSpeed: 1.5, // hur snabbt texten rör sig\n  fadeInSeconds: 1, // hur lång tid rörelsen tar på sig att \"mjukstarta\"\n};\n\n// Laserstrålar från cirklarna till musen\nconst LASER = {\n  glowWeight: 6, // tjocklek på det mjuka skenet runt strålen\n  coreWeight: 1.5, // tjocklek på själva strålen\n  glowAlpha: 35, // hur genomskinligt skenet är (0-255)\n  coreAlpha: 200, // hur genomskinlig kärnan är (0-255)\n  flickerSpeed: 12, // hur snabbt strålarna flimrar\n};\n\n// --- Tillstånd ---\nlet img; // bakgrundsbilden (finns först när den laddats klart)\nlet colorIndex = 0; // vilken textfärg som används just nu\nlet started = false; // har man klickat minst en gång?\nlet startTime = 0; // när första klicket skedde (ms)\n\nfunction setup() {\n  createCanvas(CANVAS_W, CANVAS_H);\n\n  // Ladda bilden i bakgrunden. Postern visas direkt och bilden dyker upp när den är klar.\n  loadImage(IMAGE_FILE)\n    .then((loaded) => {\n      img = loaded;\n    })\n    .catch(() => {\n      console.error(\"Kunde inte ladda bilden: \" + IMAGE_FILE + \" (kontrollera filnamnet)\");\n    });\n\n  // Be webbläsaren hämta fonterna. Vi väntar inte på dem, texten byter font när de är klara.\n  document.fonts.load(`${TITLE.size}px \"${TITLE.font}\"`).catch(() => {});\n  document.fonts.load(`700 ${NAME.size}px \"${NAME.font}\"`).catch(() => {});\n}\n\nfunction draw() {\n  background(0);\n\n  // Rita bara bilden när den har laddats klart\n  if (img) image(img, 0, 0, width, height);\n\n  const motion = getMotion();\n  drawLasers(motion); // ritas först så att cirklarna hamnar ovanpå\n  drawTexts(motion);\n  drawCircles(motion);\n}\n\n// Ger tid sedan första klicket och en \"styrka\" (0 till 1) som mjukstartar rörelsen.\n// Före första klicket är styrkan 0, alltså står allt stilla.\nfunction getMotion() {\n  if (!started) return { t: 0, strength: 0 };\n\n  const t = (millis() - startTime) / 1000;\n  const strength = constrain(t / MOVE.fadeInSeconds, 0, 1);\n  return { t, strength };\n}\n\n// Räknar ut var cirkel nummer i befinner sig just nu (övre och undre raden)\nfunction getCirclePositions(i, { t, strength }) {\n  const x = CIRCLE.margin + i * CIRCLE.spacing;\n  const wave = sin(t * MOVE.circleSpeed + i * MOVE.circlePhase);\n  const offset = wave * MOVE.circleAmp * strength;\n\n  return {\n    top: { x, y: CIRCLE.margin + offset },\n    bottom: { x, y: height - CIRCLE.margin - offset },\n  };\n}\n\nfunction drawTexts({ t, strength }) {\n  const offsetX = cos(t * MOVE.textSpeed) * MOVE.textAmp * strength;\n  const offsetY = sin(t * MOVE.textSpeed * 1.3) * MOVE.textAmp * strength;\n\n  fill(TEXT_COLORS[colorIndex]);\n  noStroke();\n  textAlign(CENTER);\n\n  textFont(TITLE.font);\n  textStyle(NORMAL);\n  textSize(TITLE.size);\n  text(TITLE.text, width / 2 + offsetX, TITLE.y + offsetY);\n\n  textFont(NAME.font);\n  textStyle(BOLD);\n  textSize(NAME.size);\n  text(NAME.text, width / 2 - offsetX, NAME.y - offsetY);\n  textStyle(NORMAL);\n}\n\nfunction drawCircles(motion) {\n  // Vita före första klicket, sedan samma färg som texten\n  fill(started ? TEXT_COLORS[colorIndex] : \"white\");\n\n  for (let i = 0; i < CIRCLE.count; i++) {\n    const { top, bottom } = getCirclePositions(i, motion);\n    ellipse(top.x, top.y, CIRCLE.diameter, CIRCLE.diameter);\n    ellipse(bottom.x, bottom.y, CIRCLE.diameter, CIRCLE.diameter);\n  }\n}\n\n// Laserstrålar från varje cirkel till musen. Syns först efter första klicket.\nfunction drawLasers(motion) {\n  if (!started) return;\n\n  const { t, strength } = motion;\n  const base = color(TEXT_COLORS[colorIndex]);\n\n  // Lätt flimmer så att strålarna känns levande\n  const flicker = 0.8 + 0.2 * sin(t * LASER.flickerSpeed);\n\n  // ADD-läge gör att strålarna lyser starkare där de korsar varandra\n  blendMode(ADD);\n  noFill();\n\n  for (let i = 0; i < CIRCLE.count; i++) {\n    const { top, bottom } = getCirclePositions(i, motion);\n\n    for (const p of [top, bottom]) {\n      // Mjukt sken runt strålen\n      base.setAlpha(LASER.glowAlpha * strength * flicker);\n      stroke(base);\n      strokeWeight(LASER.glowWeight);\n      line(p.x, p.y, mouseX, mouseY);\n\n      // Tunn, stark kärna\n      base.setAlpha(LASER.coreAlpha * strength * flicker);\n      stroke(base);\n      strokeWeight(LASER.coreWeight);\n      line(p.x, p.y, mouseX, mouseY);\n    }\n  }\n\n  // Återställ så att resten av postern ritas som vanligt\n  blendMode(BLEND);\n  noStroke();\n}\n\n// Vid musklick (vänster eller höger): byt färg och starta rörelsen första gången\nfunction mousePressed() {\n  if (!started) {\n    started = true;\n    startTime = millis();\n  }\n  colorIndex = (colorIndex + 1) % TEXT_COLORS.length;\n}", "assets": {"sebastiaan-stam-OSNHWe24YV4-unsplash.jpg": {"mime": "image/webp", "b64": ""}}});
